use std::fs

trait Shape {
    fn name(self) -> string
    fn corners(self) -> int
    fn double_area(self) -> int
}

struct Square {
    label: string,
    s: int,
}

struct Rect {
    label: string,
    w: int,
    h: int,
}

struct RTri {
    label: string,
    a: int,
    b: int,
}

struct Trap {
    label: string,
    a: int,
    b: int,
    h: int,
}

impl Shape for Square {
    fn name(self) -> string { self.label }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { 2 * self.s * self.s }
}

impl Shape for Rect {
    fn name(self) -> string { self.label }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { 2 * self.w * self.h }
}

impl Shape for RTri {
    fn name(self) -> string { self.label }
    fn corners(self) -> int { 3 }
    fn double_area(self) -> int { self.a * self.b }
}

impl Shape for Trap {
    fn name(self) -> string { self.label }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { (self.a + self.b) * self.h }
}

fn num(parts: Vec<string>, i: int) -> int {
    parts[i].parse::<int>() ?? 0
}

fn main() {
    let text = fs::read_to_string("/dev/stdin") ?? ""
    let mut shapes: Vec<Box<dyn Shape>> = Vec::new()
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let kind = parts[0]
        if kind == "square" {
            shapes.push(Box::new(Square { label: kind, s: num(parts, 1) }))
        } else if kind == "rect" {
            shapes.push(Box::new(Rect { label: kind, w: num(parts, 1), h: num(parts, 2) }))
        } else if kind == "rtri" {
            shapes.push(Box::new(RTri { label: kind, a: num(parts, 1), b: num(parts, 2) }))
        } else if kind == "trap" {
            shapes.push(Box::new(Trap { label: kind, a: num(
                parts,
                1,
            ), b: num(parts, 2), h: num(parts, 3) }))
        }
    }
    let mut total = 0
    let mut best_name = "none"
    let mut best = -1
    for sh in shapes {
        let d = sh.double_area()
        println("${sh.name()} corners=${sh.corners()} area2=${d}")
        total = total + d
        if d > best {
            best = d
            best_name = sh.name()
        }
    }
    println("total area2=${total}")
    if best < 0 {
        println("largest=none")
    } else {
        println("largest=${best_name} area2=${best}")
    }
}

